    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<int> a = {2, 4, 6, 8};
    int s = 0;
    for (int x : a)
        s += x;
    cout << s;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n = 4, count = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < i; ++j)
            ++count;
    cout << count;
}

