advanced.solutionCode:
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, x = 1;
    cin >> n;
    int k = 0;
    while (x < n) {
        x *= 2;
        ++k;
    }
    cout << k;
}
